WORDS: dict[str, dict[str, str]] = {"en": EN, "ru": RU, "uz": UZ}
MISSING: set[str] = set()  # keys that were asked for and have no English text (checked by scripts/check_block_editor.py)


def t(lang: str, key: str, **blanks) -> str:
    """The text for `key` in `lang` (English if that language does not have it yet), with its blanks filled."""
    if key not in EN:
        MISSING.add(key)
    text = WORDS.get(lang, EN).get(key) or EN.get(key, key)
    return text.format(**blanks) if blanks else text


def in_units(value, lang: str):
    """Write the volume unit the way the language does, in every text of a nested value (figures and code excepted)."""
    unit = t(lang, "unit.mm3")
    if isinstance(value, str):
        return value if value.lstrip().startswith("<svg") else value.replace("Mm³", unit)
    if isinstance(value, list):
        return [in_units(item, lang) for item in value]
    if isinstance(value, dict):
        return {key: item if key in ("code", "svg") else in_units(item, lang) for key, item in value.items()}
    return value
